using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// Set up options with a known type resolver (source-gen context)
var options = new JsonSerializerOptions
{
    TypeInfoResolver = AppJsonContext.Default
};

// 1) Strongly-typed retrieval — GetTypeInfo<T>() returns JsonTypeInfo<T> directly
JsonTypeInfo<WeatherForecast> typedInfo = options.GetTypeInfo<WeatherForecast>();
Console.WriteLine($"Got typed metadata  : {typedInfo.Type.Name}  (kind: {typedInfo.Kind})");

// Round-trip with the typed metadata to prove it works
var forecast = new WeatherForecast("Seattle", 18);
string json = JsonSerializer.Serialize(forecast, typedInfo);
WeatherForecast rt = JsonSerializer.Deserialize(json, typedInfo)!;
Console.WriteLine($"Round-tripped       : {rt}");

// 2) Probe without throwing — TryGetTypeInfo gives back non-generic JsonTypeInfo?
bool found = options.TryGetTypeInfo(typeof(WeatherForecast), out JsonTypeInfo? probed);
Console.WriteLine($"\nTryGet WeatherForecast: found={found}, type={probed?.Type.Name}");

// Try a type the resolver does NOT know about
bool foundUnknown = options.TryGetTypeInfo(typeof(Uri), out JsonTypeInfo? probedUnknown);
Console.WriteLine($"TryGet Uri            : found={foundUnknown}, info is null={probedUnknown is null}");

// Records used in the demo
public record WeatherForecast(string City, int TempC);

// Source-generated context that only knows about WeatherForecast
[JsonSerializable(typeof(WeatherForecast))]
internal partial class AppJsonContext : JsonSerializerContext;

